"""sklearn.feature_extraction.text — text feature extraction stubs.

Real sklearn provides CountVectorizer/TfidfVectorizer with full regex
tokenisation and IDF weighting. The shim provides minimal versions
that work on small inputs."""

import re as _re
import numpy as _np


_DEFAULT_TOKEN = _re.compile(r"(?u)\b\w\w+\b")


class CountVectorizer:
    """Bag-of-words count matrix builder."""

    def __init__(self, *, input='content', encoding='utf-8',
                  decode_error='strict', strip_accents=None, lowercase=True,
                  preprocessor=None, tokenizer=None, stop_words=None,
                  token_pattern=r"(?u)\b\w\w+\b", ngram_range=(1, 1),
                  analyzer='word', max_df=1.0, min_df=1, max_features=None,
                  vocabulary=None, binary=False, dtype=_np.int64):
        self.lowercase = lowercase
        self.token_pattern = _re.compile(token_pattern)
        self.ngram_range = ngram_range
        self.max_features = max_features
        self.vocabulary_ = vocabulary
        self.binary = binary
        self.stop_words = stop_words

    def _tokenize(self, text):
        if self.lowercase: text = text.lower()
        tokens = self.token_pattern.findall(text)
        if self.stop_words:
            sw = set(self.stop_words) if not isinstance(self.stop_words, str) else set()
            tokens = [t for t in tokens if t not in sw]
        # Generate ngrams.
        n_min, n_max = self.ngram_range
        out = []
        for n in range(n_min, n_max + 1):
            for i in range(len(tokens) - n + 1):
                out.append(' '.join(tokens[i:i + n]))
        return out

    def fit(self, raw_documents, y=None):
        self.fit_transform(raw_documents); return self

    def fit_transform(self, raw_documents, y=None):
        vocab = {}
        rows = []
        for doc in raw_documents:
            toks = self._tokenize(doc)
            counts = {}
            for t in toks:
                if t not in vocab:
                    vocab[t] = len(vocab)
                counts[vocab[t]] = counts.get(vocab[t], 0) + 1
            rows.append(counts)
        self.vocabulary_ = vocab
        n_features = len(vocab)
        X = _np.zeros((len(rows), n_features), dtype=int)
        for i, counts in enumerate(rows):
            for col, c in counts.items():
                X[i, col] = 1 if self.binary else c
        return X

    def transform(self, raw_documents):
        if self.vocabulary_ is None:
            raise ValueError('Vectorizer not fitted')
        n_features = len(self.vocabulary_)
        X = _np.zeros((sum(1 for _ in raw_documents), n_features), dtype=int)
        for i, doc in enumerate(raw_documents):
            for t in self._tokenize(doc):
                col = self.vocabulary_.get(t)
                if col is not None:
                    X[i, col] += 1 if not self.binary else 0
                    if self.binary: X[i, col] = 1
        return X

    def get_feature_names_out(self, input_features=None):
        inverse = {v: k for k, v in self.vocabulary_.items()}
        return _np.array([inverse[i] for i in range(len(inverse))])


class TfidfTransformer:
    """Apply TF-IDF weighting to a count matrix."""

    def __init__(self, *, norm='l2', use_idf=True, smooth_idf=True,
                  sublinear_tf=False):
        self.norm = norm; self.use_idf = use_idf
        self.smooth_idf = smooth_idf; self.sublinear_tf = sublinear_tf

    def fit(self, X, y=None):
        X = _np.asarray(X, dtype=float)
        n_samples = X.shape[0]
        df = (X > 0).sum(axis=0).astype(float)
        if self.smooth_idf:
            self.idf_ = _np.log((n_samples + 1) / (df + 1)) + 1
        else:
            df = _np.maximum(df, 1)
            self.idf_ = _np.log(n_samples / df) + 1
        return self

    def transform(self, X):
        X = _np.asarray(X, dtype=float).copy()
        if self.sublinear_tf:
            mask = X > 0
            X[mask] = 1 + _np.log(X[mask])
        if self.use_idf:
            X *= self.idf_
        if self.norm == 'l2':
            n = _np.linalg.norm(X, axis=1, keepdims=True); n[n == 0] = 1
            X /= n
        elif self.norm == 'l1':
            n = _np.abs(X).sum(axis=1, keepdims=True); n[n == 0] = 1
            X /= n
        return X

    def fit_transform(self, X, y=None):
        return self.fit(X, y).transform(X)


class TfidfVectorizer(CountVectorizer):
    """CountVectorizer + TfidfTransformer in one."""

    def __init__(self, *, input='content', encoding='utf-8',
                  decode_error='strict', strip_accents=None, lowercase=True,
                  preprocessor=None, tokenizer=None, analyzer='word',
                  stop_words=None, token_pattern=r"(?u)\b\w\w+\b",
                  ngram_range=(1, 1), max_df=1.0, min_df=1, max_features=None,
                  vocabulary=None, binary=False, dtype=_np.float64, norm='l2',
                  use_idf=True, smooth_idf=True, sublinear_tf=False):
        super().__init__(input=input, encoding=encoding,
                          decode_error=decode_error, strip_accents=strip_accents,
                          lowercase=lowercase, preprocessor=preprocessor,
                          tokenizer=tokenizer, analyzer=analyzer,
                          stop_words=stop_words, token_pattern=token_pattern,
                          ngram_range=ngram_range, max_df=max_df, min_df=min_df,
                          max_features=max_features, vocabulary=vocabulary,
                          binary=binary, dtype=dtype)
        self._tfidf = TfidfTransformer(norm=norm, use_idf=use_idf,
                                         smooth_idf=smooth_idf,
                                         sublinear_tf=sublinear_tf)

    def fit(self, raw_documents, y=None):
        X = super().fit_transform(raw_documents)
        self._tfidf.fit(X); return self

    def fit_transform(self, raw_documents, y=None):
        X = super().fit_transform(raw_documents)
        return self._tfidf.fit_transform(X)

    def transform(self, raw_documents):
        X = super().transform(raw_documents)
        return self._tfidf.transform(X)


class HashingVectorizer:
    """Hashing-trick text vectoriser — no fitted vocabulary."""

    def __init__(self, *, n_features=2 ** 20, **kwargs):
        self.n_features = n_features
        self.cv = CountVectorizer(**{k: v for k, v in kwargs.items()
                                      if k in ('lowercase', 'token_pattern',
                                                'ngram_range', 'stop_words')})

    def fit(self, X, y=None): return self

    def transform(self, raw_documents):
        out = _np.zeros((len(raw_documents), self.n_features), dtype=int)
        for i, doc in enumerate(raw_documents):
            for t in self.cv._tokenize(doc):
                col = hash(t) % self.n_features
                out[i, col] += 1
        return out

    def fit_transform(self, raw_documents, y=None):
        return self.transform(raw_documents)


# Aliases / helper names from upstream.
ENGLISH_STOP_WORDS = frozenset()
strip_accents_ascii = lambda s: s.encode('ascii', 'ignore').decode('ascii')
strip_accents_unicode = lambda s: s
strip_tags = lambda s: _re.sub(r'<[^>]+>', '', s)
